(function(){'use strict';
const $=id=>document.getElementById(id),C=window.Meydan,P=window.MeydanProtocol,storage=window.MeydanStorage||localStorage;
const sections=['welcome','host-setup','join-setup','editor','arena'];let bank=window.MEYDAN_DEMO_BANK,selection=new Set(),editIndex=-1,role='',host=null,state=null,member=null,config=null,isDemo=false,sim=[],renderVersion=-1,networkAddress='',toastTimer,quizTimers=[];
try{const b=storage.getItem('meydan-bank');if(b)bank=C.validateBank(JSON.parse(b));}catch(e){}
function show(id){for(const s of sections)$(s).hidden=s!==id;window.scrollTo(0,0);}
function toast(t){$('toast').textContent=t;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,5000);}
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function native(c){return Native.command(c).catch(e=>toast(e.message));}
async function saveBank(){await storage.setItem('meydan-bank',JSON.stringify(bank));renderBank();}
function download(name,data){const json=JSON.stringify(data,null,2);if(window.Android){native({action:'export',name,content:json});return;}const u=URL.createObjectURL(new Blob([json],{type:'application/json;charset=utf-8'}));const a=el('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function renderBank(){const b=$('question-selection');b.replaceChildren();$('bank-summary').textContent=`بنك الأسئلة · ${bank.length} سؤالًا · ${selection.size} محدد`;$('count').max=bank.length;bank.forEach((q,i)=>{const row=el('div',undefined,'selection-row'),label=el('label'),c=el('input');c.type='checkbox';c.checked=selection.has(i);c.onchange=()=>{c.checked?selection.add(i):selection.delete(i);$('count').value=selection.size||1;$('bank-summary').textContent=`بنك الأسئلة · ${bank.length} سؤالًا · ${selection.size} محدد`;};label.append(c,document.createTextNode(`${i+1}. ${q.text}`));row.append(label);b.append(row);});const l=$('editor-list');l.replaceChildren();bank.forEach((q,i)=>{const row=el('div',undefined,'selection-row');row.append(el('span',`${i+1}. ${q.text}`));const btn=el('button','تعديل');btn.onclick=()=>{editIndex=i;$('qtext').value=q.text;$('qoptions').value=q.options.join('\n');$('qanswer').value=q.answer+1;$('qseconds').value=q.seconds;$('qpoints').value=q.points;$('qexplanation').value=q.explanation;$('save-q').textContent='حفظ التعديل';window.scrollTo(0,0);};row.append(btn);l.append(row);});}
function cancelEdit(){editIndex=-1;for(const id of ['qtext','qoptions','qexplanation'])$(id).value='';$('qanswer').value=1;$('qseconds').value=20;$('qpoints').value=100;$('save-q').textContent='إضافة السؤال';}
function setupOnline(){document.querySelectorAll('.online-field').forEach(n=>n.hidden=$('host-mode').value!=='online');const bt=$('join-mode').value==='bt';$('bt-devices-wrap').hidden=!bt;$('address').parentElement.hidden=bt;$('address').placeholder=$('join-mode').value==='online'?'wss://example.com':'192.168.1.5:45871';}
function clearTimers(){quizTimers.forEach(clearTimeout);quizTimers=[];}
async function stop(){clearTimers();if(!isDemo&&Native.available)await native({action:'stop'});host=null;role='';state=null;renderVersion=-1;networkAddress='';}
function selectedBank(){const count=Number($('count').value);if(!Number.isInteger(count)||count<1||count>bank.length)throw new Error('حدد عددًا بين 1 و'+bank.length);const indexes=selection.size?Array.from(selection).sort((a,b)=>a-b):Array.from({length:count},(_,i)=>i);if(indexes.length!==count)throw new Error('عدد الأسئلة المحددة مختلف عن العدد المطلوب');return indexes.map(i=>bank[i]);}
async function startHost(demo=false,restore=false){if(!demo&&!Native.available){toast('استخدم APK أو نسخة ويندوز لاتصال الأجهزة، أو اختر التجربة الافتراضية.');return;}try{let e;if(restore){const saved=storage.getItem('meydan-session');if(!saved)throw new Error('لا توجد جلسة محفوظة');e=C.Engine.restore(JSON.parse(saved));}const chosen=e?e.questions:selectedBank();const mode=demo?'demo':$('host-mode').value;const relay=$('host-relay').value.trim(),key=$('host-key').value;if(mode==='online'&&(!/^wss:\/\//.test(relay)||key.length<12))throw new Error('حدد عنوان wss ومفتاح استضافة من 12 حرفًا على الأقل');role='host';isDemo=demo;config={mode,relay,key};host=new P.HostSession({bank:chosen,count:chosen.length,kind:mode==='bt'?'bt':'lan'},e);state=host.engine.snapshot('admin');renderVersion=-1;sim=[];if(demo){for(const name of ['الصقور','النجوم','العباقرة','الروّاد'])sim.push(host.engine.join({room:host.engine.room,name:'لاعب '+name,team:name},Date.now()));}else await native({action:'host',mode,room:host.engine.room,relay,key});show('arena');$('admin-controls').hidden=false;$('capacity').hidden=demo;$('reconnect').hidden=true;$('demo-note').hidden=!demo;render();saveSession(false);}catch(e){toast(e.message);}}
function join(retry=false){const mode=$('join-mode').value,address=mode==='bt'?$('bt-devices').value:$('address').value.trim();if(!Native.available){toast('افتح APK أو نسخة ويندوز للانضمام عبر الأجهزة.');return;}if(!/^\d{6}$/.test($('room').value.trim())){toast('أدخل رمز المسابقة المكوّن من ستة أرقام');return;}if(mode==='online'&&!/^wss:\/\//.test(address)){toast('استخدم عنوان wss لخادم الإنترنت');return;}const room=$('room').value.trim();let old;try{old=JSON.parse(storage.getItem('meydan-player-'+room));}catch(e){}if(!retry&&(!$('name').value.trim()||!$('team').value.trim())){toast('أدخل اسمك واسم الفريق');return;}if(retry&&!old){toast('لا توجد هوية اتصال سابقة لهذه المسابقة');return;}role='player';isDemo=false;host=null;config={mode,address,room,name:$('name').value.trim(),team:$('team').value.trim(),resume:retry?old?.token:undefined};state=null;renderVersion=-1;native({action:'join',mode,address,room});toast('جارٍ الاتصال…');}
function send(peerId,m){native({action:'send',peerId,line:JSON.stringify(m)});}
function fanout(out){for(const o of out)send(o.peerId,o.message);}
function admin(m){if(!host)return;const r=host.engine.dispatch('admin',m,Date.now());if(!r.accepted){toast(r.reason);return;}fanout(host.snapshots());render();saveSession(false);if(m.type==='open'&&isDemo){clearTimers();for(const p of sim){const delay=800+Math.random()*Math.max(500,host.engine.questions[host.engine.index].seconds*650);quizTimers.push(setTimeout(()=>{if(!host)return;const q=host.engine.questions[host.engine.index];host.engine.dispatch(p.memberId,{type:host.engine.mode==='buzz'?'buzz':'answer',choice:Math.random()<.65?q.answer:Math.floor(Math.random()*q.options.length),round:host.engine.round,id:C.uid()},Date.now());render();},delay));}}}
async function saveSession(notify=true){if(host){try{await storage.setItem('meydan-session',JSON.stringify(host.engine.save()));if(notify)toast('حُفظت الجلسة على هذا الجهاز');}catch(e){toast('تعذر الحفظ: مساحة الجهاز غير كافية');}}}
function playerAction(m){if(!state||!member)return;send('host',{...m,round:state.round,id:C.uid()});}
window.meydanEvent=function(e){try{if(e.type==='error'){toast(e.message||'تعذر الاتصال');return;}if(e.type==='devices'){const list=$('bt-devices');list.replaceChildren();for(const d of e.devices||[]){const o=el('option',d.name+' · '+d.address);o.value=d.address;list.append(o);}if(!list.options.length)toast('لا توجد أجهزة مقترنة. افتح إعدادات البلوتوث واقترن بجهاز المدير.');return;}if(e.type==='hosting'){networkAddress=e.address||'';render();toast('الجلسة جاهزة لاستقبال الفرق');return;}if(e.type==='connected'&&role==='player'){send('host',{type:'join',room:config.room,name:config.name,team:config.team,resume:config.resume});return;}if(e.type==='disconnected'){if(role==='host'&&host){host.remove(e.peerId);render();}else{toast('انقطع الاتصال. استخدم إعادة الاتصال لاستئناف هويتك.');$('reconnect').hidden=false;}return;}if(e.type!=='line')return;const m=P.decode(e.line);if(role==='host'&&host){const previousVersion=host.engine.stateVersion;fanout(host.receive(e.peerId,m,Date.now()));render();if(previousVersion!==host.engine.stateVersion)saveSession(false);return;}if(role!=='player')return;if(m.type==='joined'){member=m;config.resume=m.token;Promise.resolve(storage.setItem('meydan-player-'+config.room,JSON.stringify({memberId:m.memberId,teamId:m.teamId,token:m.token}))).catch(err=>toast(err.message));if(m.state){state=m.state;clockOffset=Number.isFinite(m.serverNow)?m.serverNow-Date.now():0;renderVersion=-1;render();}show('arena');$('admin-controls').hidden=true;$('capacity').hidden=true;$('demo-note').hidden=true;$('reconnect').hidden=true;toast('أهلًا بك في الميدان');}if(m.type==='ping'){if(Number.isFinite(m.serverNow))clockOffset=m.serverNow-Date.now();send('host',{type:'pong',seq:m.seq});}if(m.type==='state'&&member){if(state&&m.state.stateVersion<state.stateVersion)return;if(Number.isFinite(m.serverNow))clockOffset=m.serverNow-Date.now();state=m.state;render();}if(m.type==='error')toast(m.reason);if(m.type==='ack')toast('تم اعتماد مشاركة فريقك');}catch(err){toast('رسالة اتصال غير صالحة');}};
function render(){if(host)state=host.engine.snapshot('admin');if(!state)return;$('room-code').textContent=state.room;$('connection-address').textContent=networkAddress;$('role-label').textContent=role==='host'?'مدير المسابقة'+(isDemo?' · محاكاة':''):config.name+' · '+config.team;$('arena-title').textContent=state.status==='finished'?'انتهى التحدي. تهانينا للفائزين!':state.status==='waiting'?'الميدان جاهز':state.status==='revealed'?'لحظة الحقيقة':'التحدي مفتوح';renderTimer();renderCapacity();if(renderVersion===state.stateVersion)return;renderVersion=state.stateVersion;
$('question-position').textContent=state.index<0?`${state.count} سؤالًا في هذه المسابقة`:`السؤال ${state.index+1} / ${state.count}`;$('question-type').textContent=state.mode==='buzz'?'أول ضغطة':state.mode==='team'?'إجابة جماعية':'اختيار متعدد';$('multiplier-badge').textContent=state.multiplier>1?'النقاط ×'+state.multiplier:'';$('question-text').textContent=state.question?.text||'الميدان جاهز. ننتظر إشارة البداية.';const choices=$('choices');choices.replaceChildren();const revealed=['revealed','finished'].includes(state.status);if(state.question&&state.mode!=='buzz'){state.question.options.forEach((opt,i)=>{const b=el('button',undefined,'choice');b.append(el('span',['أ','ب','ج','د','هـ','و'][i]),el('span',opt));if(revealed&&i===state.question.answer)b.classList.add('correct');b.disabled=role==='host'||state.status!=='open'||state.submitted;b.onclick=()=>{if(window.confirm('اعتماد إجابة فريقك: '+opt+'؟ لا يمكن تعديلها بعد التأكيد.'))playerAction({type:'answer',choice:i});};choices.append(b);});}$('explanation').hidden=!revealed||!state.question;$('explanation').textContent=state.question?.explanation||'';$('buzz').hidden=state.mode!=='buzz'||role!=='player';$('buzz').disabled=state.status!=='open'||state.pressed;$('answer-state').textContent=state.submitted?'اعتمدت إجابة فريقك. انتظر كشف الحل.':state.pressed?'سُجلت ضغطة فريقك. انتظر حكم المدير.':state.status==='locked'?'انتهى وقت الإجابة.':state.status==='open'&&role==='player'?'اختر الإجابة وأكدها أو اضغط أولًا.':'';
const order=$('buzz-order');order.replaceChildren();if(state.mode==='buzz')state.buzzes.forEach((b,i)=>{const p=state.members.find(p=>p.id===b.memberId);order.append(el('div',`${i+1}. ${p?.name||''}`,i===state.buzzIndex?'buzz-entry active':'buzz-entry'));});
const scores=$('scores');scores.replaceChildren();[...state.teams].sort((a,b)=>b.score-a.score).forEach((t,i)=>{const r=el('div',undefined,'score-row');r.append(el('span',String(i+1).padStart(2,'0'),'rank'),el('span',t.name,'team'),el('span',String(t.score),'points'));if(role==='host'){const b=el('button','±','adjust');b.setAttribute('aria-label','تعديل نقاط '+t.name);b.onclick=()=>{const v=prompt('تعديل نقاط '+t.name+' (مثال 100 أو -50)');if(v!==null)admin({type:'adjust',teamId:t.id,delta:Number(v)});};r.append(b);}scores.append(r);});const members=$('members');members.replaceChildren(el('strong',`${state.members.length} لاعبًا · ${state.teams.length} فرق`));state.members.forEach(p=>{const t=state.teams.find(t=>t.id===p.teamId);members.append(el('div',`${p.name} / ${t?.name||''}`,'member-line'));});
if(role==='host'){const q=$('next-question'),v=q.value;q.replaceChildren();host.engine.questions.forEach((x,i)=>{if(state.completed.includes(i))return;const o=el('option',`${i+1}. ${x.text}`);o.value=i;q.append(o);});if([...q.options].some(o=>o.value===v))q.value=v;$('open').disabled=['open','locked','finished'].includes(state.status)||!q.options.length;$('lock').disabled=state.status!=='open';$('reveal').disabled=!['open','locked'].includes(state.status);$('judge-yes').hidden=$('judge-no').hidden=state.mode!=='buzz';$('judge-yes').disabled=$('judge-no').disabled=state.scored||!state.buzzes[state.buzzIndex]||!['open','locked'].includes(state.status);}}
function renderTimer(){if(!state)return;const sec=state.status==='open'?Math.max(0,Math.ceil((state.deadline-(Date.now()+clockOffset))/1000)):state.status==='locked'?0:null;$('timer').textContent=sec===null?'—':sec;$('timer').classList.toggle('urgent',sec!==null&&sec<=5);}
let clockOffset=0;
function renderCapacity(){if(!host||isDemo)return;const r=host.capacity.report(Date.now());$('capacity-text').textContent=`${config.mode==='bt'?'بلوتوث':config.mode==='online'?'إنترنت':'شبكة محلية'} · ${host.peers.size} متصل · السعة المقدّرة ${r.limit} · ثبت استقرار ${r.verified} · ${Math.round(r.p95)} ms · ${r.healthy?'مستقر':'الانضمام متوقف مؤقتًا'}`;}
$('host-role').onclick=()=>{renderBank();show('host-setup');};$('player-role').onclick=()=>show('join-setup');document.querySelectorAll('.back').forEach(b=>b.onclick=()=>show('welcome'));$('demo').onclick=()=>{selection.clear();$('count').value=Math.min(10,bank.length);startHost(true);};$('create').onclick=()=>startHost();$('restore').onclick=()=>startHost(false,true);$('host-mode').onchange=$('join-mode').onchange=setupOnline;$('devices').onclick=()=>native({action:'devices'});$('join').onclick=()=>join();$('retry').onclick=()=>join(true);$('reconnect').onclick=()=>join(true);$('leave').onclick=async()=>{if(!confirm('مغادرة المسابقة؟'))return;saveSession(false);await stop();show('welcome');};$('edit-bank').onclick=()=>{renderBank();show('editor');};$('editor-back').onclick=()=>{renderBank();show('host-setup');};$('cancel-edit').onclick=cancelEdit;
$('save-q').onclick=async()=>{try{const q=C.validateBank([{text:$('qtext').value,options:$('qoptions').value.split('\n').filter(s=>s.trim()),answer:Number($('qanswer').value)-1,seconds:Number($('qseconds').value),points:Number($('qpoints').value),explanation:$('qexplanation').value}])[0];if(editIndex>=0)bank[editIndex]=q;else bank.push(q);await saveBank();cancelEdit();toast('حُفظ السؤال');}catch(e){toast(e.message);}};$('export-bank').onclick=()=>download('meydan-questions.json',bank);$('import-bank').onchange=async()=>{const f=$('import-bank').files[0];if(!f)return;try{if(f.size>5*1024*1024)throw new Error('حجم الملف أكبر من 5 ميجابايت');const b=C.validateBank(JSON.parse(await f.text()));if(!confirm('استبدال البنك الحالي بـ '+b.length+' سؤالًا؟'))return;bank=b;selection.clear();await saveBank();toast('تم الاستيراد');}catch(e){toast(e.message);}};
$('select-first').onclick=()=>{selection.clear();const n=Math.min(bank.length,Math.max(1,Number($('count').value)||1));for(let i=0;i<n;i++)selection.add(i);$('count').value=n;renderBank();};$('clear-selection').onclick=()=>{selection.clear();renderBank();};$('calibrate').onchange=()=>{if(host)host.capacity.calibrating=$('calibrate').checked;};$('open').onclick=()=>admin({type:'open',index:Number($('next-question').value),mode:$('round-mode').value,multiplier:Number($('round-multiplier').value)});$('lock').onclick=()=>admin({type:'lock'});$('reveal').onclick=()=>admin({type:'reveal'});$('judge-yes').onclick=()=>admin({type:'judge',correct:true});$('judge-no').onclick=()=>admin({type:'judge',correct:false});$('finish').onclick=()=>admin({type:'finish'});$('save-session').onclick=()=>saveSession();$('export-results').onclick=()=>{if(host)download('meydan-results.json',{room:host.engine.room,teams:host.engine.teams,members:host.engine.members.map(({name,teamId})=>({name,teamId})),log:host.engine.log});};$('buzz').onclick=()=>playerAction({type:'buzz'});$('fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen?.().catch(()=>toast('ملء الشاشة غير متاح هنا'));};
setInterval(()=>{if(host){const previousVersion=host.engine.stateVersion;fanout(host.tick(Date.now()));if(previousVersion!==host.engine.stateVersion)saveSession(false);render();}else renderTimer();},250);renderBank();setupOnline();
})();
